using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests;

public sealed class GoldDiscountTests
{
    // No checkout API exists yet, so the outcome is probed by type name rather than by a compile-time reference.
    [Fact]
    public void GoldCustomerWithSubtotal100PaysApprovedTotalOf95()
    {
        var checkout = typeof(ApplicationMarker).Assembly.GetTypes()
            .FirstOrDefault(t => t.IsPublic && t.Name.Contains("Checkout", StringComparison.OrdinalIgnoreCase));

        Assert.True(checkout is not null,
            "Expected 100.00 Gold subtotal to produce a payable total of 95.00, but the Application assembly has no checkout/pricing type to calculate it.");
    }
}
